 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    border = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    seen = set()
    q = deque()
    # Exterior is the connected region of non-border color touching the edge.
    for r in range(h):
        for c in range(w):
            if (r == 0 or c == 0 or r == h-1 or c == w-1) and grid[r][c] != border:
                if (r,c) not in seen:
                    seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != border and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != border and (r,c) not in seen:
                out[r][c]=4
    return out
